import{_ as p,a0 as o,w as s,s as l,ao as d,I as u,x as e,a1 as a,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何从Ubuntu13.04 升级到Ubuntu13.10 Saucy Salamander | LCTT x X-CMD","titleTemplate":false,"description":"如何从Ubuntu13.04 升级到Ubuntu13.10 Saucy Salamander | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从Ubuntu13.04 升级到Ubuntu13.10 Saucy Salamander | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从Ubuntu13.04 升级到Ubuntu13.10 Saucy Salamander | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/How To Upgrade From Ubuntu 13.04 Raring To Ubuntu 13.10 Saucy Salamander","title":"如何从Ubuntu13.04 升级到Ubuntu13.10 Saucy Salamander","tag":"201310","desc":""},"relativePath":"201310/How To Upgrade From Ubuntu 13.04 Raring To Ubuntu 13.10 Saucy Salamander.md","filePath":"[post].md"}'),i={name:"201310/How To Upgrade From Ubuntu 13.04 Raring To Ubuntu 13.10 Saucy Salamander.md"};function g(m,t,b,U,w,c){const n=o("Link");return s(),l("div",null,[t[14]||(t[14]=d(`<h1 id="如何从ubuntu13-04-升级到ubuntu13-10-saucy-salamander" tabindex="-1">如何从Ubuntu13.04 升级到Ubuntu13.10 Saucy Salamander <a class="header-anchor" href="#如何从ubuntu13-04-升级到ubuntu13-10-saucy-salamander" aria-label="Permalink to “如何从Ubuntu13.04 升级到Ubuntu13.10 Saucy Salamander”">​</a></h1><p><strong>Ubuntu 13.10 Saucy</strong>已于<strong>10月17日</strong>发布。希望它比Ubuntu 13.04 Raring版本或以前的版本有很大的改进及增加更多功能。大家都好奇地等着，想看看Ubuntu13.10将给Ubuntu爱好者带来些什么。</p><p>如果你的系统是Ubuntu的13.04、12.10、12.04 Precise Pangolin或者更早的版本的话，你愿意升级到这最新的发行版本吗？我知道你愿意。只需要按照下面所示的简单几步，不管你用的是桌面版本还是服务器版本，都能轻松地从Ubuntu13.04版本升级到Ubuntu 13.10 Saucy版本。</p><p><strong>注意</strong>：在升级前，确保对你的 <strong>数据做一次全备份</strong>，备份存储到外部设备（USB记忆棒或CD/ DVD）。</p><p>###桌面版升级</p><p>在升级前，我们首先得更新系统，按下快捷键打开终端输入如下命令。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade
</code></pre><p>然后就可以升级到最新的发行版本了。</p><pre><code>sudo update-manager -d
</code></pre><p>Software Updater将会打开并且搜索新的发布版本。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Software-Updater_001.png" alt=""></p><p>几秒钟以后，你会看到如下所示，标有“<strong>However, Ubuntu 13.10 is available now (you have 13.04)</strong>”字样的窗口。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Software-Updater_002.png" alt=""></p><p>然后点击<strong>Upgrade</strong>按钮。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Release-Notes_003.png" alt=""></p><p>Software Updater会让你确认是否仍要升级。点击<strong>Start Upgrade</strong>就真正开始安装Ubuntu 13.10了。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Untitled-window_005.png" alt=""></p><p>现在Software Updater就会获取文件包并进行安装。这将需要一段时间，具体时间长短取决于你的网络连接速度。坐下来放松片刻吧。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Distribution-Upgrade_006.png" alt=""></p><p>过一会儿，你将被询问是否删除不必要的应用程序。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Untitled-window_008.png" alt=""></p><p>最后，点击重启完成升级。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Untitled-window_009.png" alt=""></p><p>现在你的系统就是最新的Ubuntu 13.10发布版本了。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Details_010.png" alt=""></p><p>###服务器版升级</p><p>要从Ubuntu 13.10服务器版升级到Ubuntu 13.04服务器版本，请按下面步骤操作。</p><p>如果还没有安装 <strong>update-manager-core</strong> 软件包，请先安装它：</p><pre><code>sudo apt-get install update-manager-core
</code></pre><p>打开 <strong>/etc/update-manager/release-upgrades</strong> 文件，</p><pre><code>sudo nano /etc/update-manager/release-upgrades
</code></pre><p>按如下所示进行编辑，设置 <strong>Prompt=normal</strong>。</p><pre><code># Default behavior for the release upgrader.

[DEFAULT]
# Default prompting behavior, valid options:
#
#  never  - Never check for a new release.
#  normal - Check to see if a new release is available.  If more than one new
#       release is found, the release upgrader will attempt to upgrade to
#       the release that immediately succeeds the currently-running
#       release.
#  lts- Check to see if a new LTS release is available.  The upgrader
#       will attempt to upgrade to the first LTS release available after
#       the currently-running one.  Note that this option should not be
#       used if the currently-running release is not itself an LTS
#       release, since in that case the upgrader won&#39;t be able to
#       determine if a newer release is available.
Prompt=normal
</code></pre><p>现在就可以把系统升级到最新服务器版本了，使用下面的命令：</p><pre><code>sudo do-release-upgrade -d
</code></pre><p>按照屏幕上的指示一步一步操作。大功告成！！</p>`,36)),u("p",null,[t[1]||(t[1]=e("已经成功的升级到Ubuntu 13.10了，现在该做些什么呢？看看我们的新文章“",-1)),a(n,{href:"http://www.unixmen.com/top-things-installing-ubuntu-13-10/"},{default:r(()=>[...t[0]||(t[0]=[e("安装Ubuntu13.10后最应该做的几件事",-1)])]),_:1}),t[2]||(t[2]=e("”。现在你的系统已经很完善了。庆祝吧！！",-1))]),t[15]||(t[15]=u("hr",null,null,-1)),u("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://www.unixmen.com/upgrade-ubuntu-13-04-raring-ubuntu-13-10-saucy-salamander/"},{default:r(()=>[...t[3]||(t[3]=[e("http://www.unixmen.com/upgrade-ubuntu-13-04-raring-ubuntu-13-10-saucy-salamander/",-1)])]),_:1})]),u("p",null,[t[7]||(t[7]=e("译者：",-1)),a(n,{href:"https://github.com/runningwater"},{default:r(()=>[...t[5]||(t[5]=[e("runningwater",-1)])]),_:1}),t[8]||(t[8]=e(" 校对：",-1)),a(n,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...t[6]||(t[6]=[e("Caroline",-1)])]),_:1})]),u("p",null,[t[11]||(t[11]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:r(()=>[...t[10]||(t[10]=[e("Linux中国",-1)])]),_:1}),t[13]||(t[13]=e(" 荣誉推出",-1))])])}const h=p(i,[["render",g]]);export{T as __pageData,h as default};
